package validation
import("testing"; collectorv1 "github.com/h66rogi/rogi-collector/proto/gen/collector/v1"; "google.golang.org/protobuf/types/known/timestamppb"; "time")
func TestDonationSemanticBounds(t *testing.T){valid:=&collectorv1.DonationEvent{SchemaVersion:"v1",EventType:"donation",EventId:"e",ChannelId:"c",Platform:collectorv1.Platform_PLATFORM_SOOP,PlatformChannelId:"pc",NativeBalloonCount:MaxNativeBalloonCount,NativeCurrency:collectorv1.NativeCurrency_NATIVE_CURRENCY_SOOP_BALLOON,DonationKind:"unknown_future",DonorId:"d",ConnectionEpoch:"x",ConnectionSequence:1,Cursor:&collectorv1.Cursor{JournalGeneration:"g",ChannelOffset:1},IdentityStatus:collectorv1.IdentityStatus_IDENTITY_STATUS_OBSERVATION_ONLY,ObservedAt:timestamppb.New(time.Unix(1,0))};if err:=Donation(valid);err!=nil{t.Fatal(err)};valid.NativeBalloonCount=MaxNativeBalloonCount+1;if Donation(valid)==nil{t.Fatal("unsafe native count accepted")};valid.NativeBalloonCount=1;valid.ObservedAt=nil;if Donation(valid)==nil{t.Fatal("missing observed_at accepted")};valid.ObservedAt=timestamppb.New(time.Unix(1,0));valid.EventId="";if Donation(valid)==nil{t.Fatal("missing identity accepted")}}
